get_tax_settings.code:
import {taxSettings} from 'webcommander-sdk';

const response = await taxSettings.getTaxSettings(client);
const settings = response.map.tax_settings;
console.log(settings.default_country, settings.default_tax_code, settings.default_tax_profile);
console.log(settings.show_price_with_tax, settings.tax_message);

put_tax_settings.code:
import {taxSettings} from 'webcommander-sdk';

const response = await taxSettings.putTaxSettings(client, {settings: {tax_message: 'All prices include GST'}});
console.log(response.map.tax_settings.tax_message);
